@ObservationalSUCC.ObservatorisQuantale.closed_star : ∀ {V : Type u_1} {X : Type u_2}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) {R : X → X → V} {φ : X → V},
  ObservationalSUCC.ObservatorisQuantale.Closed K R φ →
    ∀ (x z : X), K.le (K.mul (φ x) (ObservationalSUCC.ObservatorisQuantale.star K R x z)) (φ z)

@ObservationalSUCC.ObservatorisQuantale.star_closed : ∀ {V : Type u_1} {X : Type u_2}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (x : X),
  ObservationalSUCC.ObservatorisQuantale.Closed K R (ObservationalSUCC.ObservatorisQuantale.star K R x)

@ObservationalSUCC.ObservatorisQuantale.star_le_of_closed : ∀ {V : Type u_1} {X : Type u_2}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) {R : X → X → V} {φ : X → V},
  ObservationalSUCC.ObservatorisQuantale.Closed K R φ →
    ∀ {x : X}, K.le K.one (φ x) → ∀ (z : X), K.le (ObservationalSUCC.ObservatorisQuantale.star K R x z) (φ z)

@ObservationalSUCC.ObservatorisQuantale.star_le_quot_star : ∀ {V : Type u_1} {X : Type u_2} {Y : Type u_3}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y) (x z : X),
  K.le (ObservationalSUCC.ObservatorisQuantale.star K R x z)
    (ObservationalSUCC.ObservatorisQuantale.star K (ObservationalSUCC.ObservatorisQuantale.quot K R q) (q x) (q z))

@ObservationalSUCC.ObservatorisQuantale.push_star_le_quot_star : ∀ {V : Type u_1} {X : Type u_2} {Y : Type u_3}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y) (x : X) (b : Y),
  K.le (ObservationalSUCC.ObservatorisQuantale.push K q (ObservationalSUCC.ObservatorisQuantale.star K R x) b)
    (ObservationalSUCC.ObservatorisQuantale.star K (ObservationalSUCC.ObservatorisQuantale.quot K R q) (q x) b)

@ObservationalSUCC.ObservatorisQuantale.exactAt_iff_saturated_star_closed : ∀ {V : Type u_1} {X : Type u_2}
  {Y : Type u_3} (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y) (x : X),
  ObservationalSUCC.ObservatorisQuantale.ExactAt K R q x ↔
    ObservationalSUCC.ObservatorisQuantale.Closed K R fun s =>
      ObservationalSUCC.ObservatorisQuantale.push K q (ObservationalSUCC.ObservatorisQuantale.star K R x) (q s)

@ObservationalSUCC.ObservatorisQuantale.exact_iff_fibreConstant : ∀ {V : Type u_1} {X : Type u_2} {Y : Type u_3}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y),
  ObservationalSUCC.ObservatorisQuantale.EndpointExact K R q ↔
    ObservationalSUCC.ObservatorisQuantale.FibreConstant K R q

@ObservationalSUCC.ObservatorisQuantale.exact_iff_satClosed : ∀ {V : Type u_1} {X : Type u_2} {Y : Type u_3}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y),
  ObservationalSUCC.ObservatorisQuantale.EndpointExact K R q ↔ ObservationalSUCC.ObservatorisQuantale.SatClosed K R q

@ObservationalSUCC.ObservatorisQuantale.exact_iff_pushClosed : ∀ {V : Type u_1} {X : Type u_2} {Y : Type u_3}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y),
  ObservationalSUCC.ObservatorisQuantale.EndpointExact K R q ↔ ObservationalSUCC.ObservatorisQuantale.PushClosed K R q

@ObservationalSUCC.ObservatorisQuantale.quotAll_star_le_push_star : ∀ {V : Type u_1} {X : Type u_2} {Y : Type u_3}
  (K : ObservationalSUCC.ObservatorisQuantale.LaxQuantale V) (R : X → X → V) (q : X → Y) (x : X) (b : Y),
  K.le (ObservationalSUCC.ObservatorisQuantale.star K (ObservationalSUCC.ObservatorisQuantale.quotAll K R q) (q x) b)
    (ObservationalSUCC.ObservatorisQuantale.push K q (ObservationalSUCC.ObservatorisQuantale.star K R x) b)

@ObservationalSUCC.ObservatorisQuantale.star_propQ_iff : ∀ {X : Type u_1} (R : X → X → Prop) (x z : X),
  ObservationalSUCC.ObservatorisQuantale.star ObservationalSUCC.ObservatorisQuantale.propQ R x z ↔
    ObservationalSUCC.ObservatorisQuantale.Reach R x z
